def slugify(title):
    s = title.lower()
    s = s.replace('&', ' and ')
    s = re.sub(r'[^a-z0-9 -]', '', s)
    s = re.sub(r'[ -]+', '-', s)
    s = s.strip('-')
    if len(s) > 40:
        s = s[:40].rstrip('-')
    return s
